import type { LocationQuery, LocationQueryRaw } from 'vue-router';
import type {
  CanvassingProjectOnboardingFlag,
  OnboardingFlag,
  OnboardingState,
  OnboardingStateFilter,
  ProjectCanvasserResponse,
  ProjectOnboardingFilter,
  ProjectOnboardingState,
} from '~/client';
import {
  canvassingProjectOnboardingStateCheckmarkOrder,
  getProjectOnboardingFlagMissingLabel,
  getProjectOnboardingStateLabel,
} from '~/constants/users/userProjectOnboardingStatuses';
import {
  getOnboardingFlagMissingLabel,
  getOnboardingStateLabel,
  onboardingStateCheckmarkOrder,
  userOnboardingFlags,
} from '~/constants/users/userRecruitmentStatuses';

// Every checkmark filter — user onboarding and per-project onboarding alike — is
// stored as one flat boolean query param per checkmark (?good_to_hire=true). The
// three helpers below implement that encoding once, keyed by the canonical order
// of the checkmark set; the exported wrappers just bind their own order list.

function readCheckmarkParam(query: LocationQuery, checkmark: string): 'true' | 'false' | undefined {
  const raw = query[checkmark];
  const param = Array.isArray(raw) ? raw[raw.length - 1] : raw;
  return param === 'true' || param === 'false' ? param : undefined;
}

// Iterates the canonical order so output is stable.
// Returns `undefined` (not []) when no key is set so the field is omitted from the request body.
function parseCheckmarkFilters<CheckmarkT extends string>(
  query: LocationQuery,
  order: CheckmarkT[]
): { checkmark: CheckmarkT; value: boolean }[] | undefined {
  const filters = order.flatMap((checkmark) => {
    const param = readCheckmarkParam(query, checkmark);
    return param === undefined ? [] : [{ checkmark, value: param === 'true' }];
  });
  return filters.length > 0 ? filters : undefined;
}

// Serializes the same query into the ["good_to_hire=true", ...] string[] form
// used as a stable, JSON-friendly useQuery cache key.
function serializeCheckmarkFiltersForKey<CheckmarkT extends string>(
  query: LocationQuery,
  order: CheckmarkT[]
): string[] {
  return order.flatMap((checkmark) => {
    const param = readCheckmarkParam(query, checkmark);
    return param === undefined ? [] : [`${checkmark}=${param}`];
  });
}

// Produces the next route query for navigateTo: clears every key of this
// checkmark set, sets the selected filters, and resets pagination.
function buildCheckmarkQuery<CheckmarkT extends string>(
  currentQuery: LocationQuery,
  order: CheckmarkT[],
  filters: { checkmark: CheckmarkT; value: boolean }[]
): LocationQueryRaw {
  const query: LocationQueryRaw = { ...currentQuery };
  order.forEach((checkmark) => {
    delete query[checkmark];
  });
  filters.forEach((filter) => {
    query[filter.checkmark] = String(filter.value);
  });
  return { ...query, page: 1 };
}

export function parseOnboardingStateFromQuery(query: LocationQuery): OnboardingStateFilter[] | undefined {
  return parseCheckmarkFilters(query, onboardingStateCheckmarkOrder);
}

export function serializeOnboardingStateForKey(query: LocationQuery): string[] {
  return serializeCheckmarkFiltersForKey(query, onboardingStateCheckmarkOrder);
}

export function buildOnboardingStateQuery(
  currentQuery: LocationQuery,
  filters: OnboardingStateFilter[]
): LocationQueryRaw {
  return buildCheckmarkQuery(currentQuery, onboardingStateCheckmarkOrder, filters);
}

export function parseProjectOnboardingStateFromQuery(query: LocationQuery): ProjectOnboardingFilter[] | undefined {
  return parseCheckmarkFilters(query, canvassingProjectOnboardingStateCheckmarkOrder);
}

export function serializeProjectOnboardingStateForKey(query: LocationQuery): string[] {
  return serializeCheckmarkFiltersForKey(query, canvassingProjectOnboardingStateCheckmarkOrder);
}

export function buildProjectOnboardingStateQuery(
  currentQuery: LocationQuery,
  filters: ProjectOnboardingFilter[]
): LocationQueryRaw {
  return buildCheckmarkQuery(currentQuery, canvassingProjectOnboardingStateCheckmarkOrder, filters);
}

// Canonical order restricted to the 7 OnboardingFlag steps (excludes the 4
// HiringCheckmark keys: application_completed, social_media_checked,
// good_to_hire, do_not_hire). Shared by both alerts so ordering matches the
// filter selector.
const onboardingFlagOrder = onboardingStateCheckmarkOrder.filter(
  (checkmark): checkmark is OnboardingFlag => checkmark in userOnboardingFlags
);

// turn the per-flag missing-counts map into an ordered list of the
// onboarding steps that at least one assigned canvasser is missing.
// Labels are phrased in the negative (e.g. "Canvasser info NOT filled") since
// each entry represents a problem — a step that is not yet completed.
export function getMissingOnboardingCounts(
  counts: ProjectCanvasserResponse['onboarding_missing_counts']
): { checkmark: OnboardingFlag; label: string; count: number }[] {
  return onboardingFlagOrder.flatMap((checkmark) => {
    const count = counts[checkmark];
    if (!count || count <= 0) return [];
    return [{ checkmark, label: getOnboardingFlagMissingLabel(checkmark), count }];
  });
}

// list the onboarding steps a single canvasser has not completed.
// A step counts as incomplete only when present in the state and explicitly
// false, so absent keys (e.g. a subcontractor's missing flags) are skipped.
export function getIncompleteOnboardingFlags(state: OnboardingState): { checkmark: OnboardingFlag; label: string }[] {
  const checkmarks = state.checkmarks as Partial<Record<OnboardingFlag, boolean>>;
  return onboardingFlagOrder.flatMap((checkmark) =>
    checkmarks[checkmark] === false ? [{ checkmark, label: getOnboardingStateLabel(checkmark).label }] : []
  );
}

// Project-level counterparts of the two functions above. Same skip semantics, but keyed by
// the project onboarding flags — the API only returns these for canvassing projects, so an
// empty result is the normal case on a signature project rather than "nothing missing".
export function getMissingProjectOnboardingCounts(
  counts: ProjectCanvasserResponse['project_onboarding_missing_counts']
): { checkmark: CanvassingProjectOnboardingFlag; label: string; count: number }[] {
  return canvassingProjectOnboardingStateCheckmarkOrder.flatMap((checkmark) => {
    const count = counts[checkmark];
    if (!count || count <= 0) return [];
    return [{ checkmark, label: getProjectOnboardingFlagMissingLabel(checkmark), count }];
  });
}

export function getIncompleteProjectOnboardingFlags(
  state: ProjectOnboardingState
): { checkmark: CanvassingProjectOnboardingFlag; label: string }[] {
  const checkmarks = state.checkmarks as Partial<Record<CanvassingProjectOnboardingFlag, boolean>>;
  return canvassingProjectOnboardingStateCheckmarkOrder.flatMap((checkmark) =>
    checkmarks[checkmark] === false ? [{ checkmark, label: getProjectOnboardingStateLabel(checkmark).label }] : []
  );
}
