import type { CanvassingProjectOnboardingFlag, ProjectOnboardingFlag, ProjectType } from '~/client';

export const userProjectOnboardingFlags: Record<CanvassingProjectOnboardingFlag, { label: string }> = {
  app_username_assigned: { label: 'App username assigned' },
};

export const projectOnboardingStateLabels: Record<ProjectOnboardingFlag, { label: string }> = {
  ...userProjectOnboardingFlags,
};

export function getProjectOnboardingStateLabel(flag: ProjectOnboardingFlag): { label: string } {
  return projectOnboardingStateLabels[flag] ?? { label: snakeCaseToCapitalizedCase(flag) };
}

export const projectOnboardingFlagMissingLabels: Record<ProjectOnboardingFlag, string> = {
  app_username_assigned: 'App username NOT assigned',
};

export function getProjectOnboardingFlagMissingLabel(flag: ProjectOnboardingFlag): string {
  return projectOnboardingFlagMissingLabels[flag] ?? snakeCaseToCapitalizedCase(flag);
}

export const canvassingProjectOnboardingStateCheckmarkOrder: CanvassingProjectOnboardingFlag[] = [
  'app_username_assigned',
];

export const signatureProjectOnboardingStateCheckmarkOrder: ProjectOnboardingFlag[] = [];

const projectOnboardingCheckmarkOrders: Record<ProjectType, CanvassingProjectOnboardingFlag[]> = {
  canvassing: canvassingProjectOnboardingStateCheckmarkOrder,
  signature: signatureProjectOnboardingStateCheckmarkOrder,
};

export function getProjectOnboardingCheckmarkOrder(
  projectType: ProjectType | undefined
): CanvassingProjectOnboardingFlag[] {
  return projectType === undefined ? [] : (projectOnboardingCheckmarkOrders[projectType] ?? []);
}
