import type { HiringCheckmark, OnboardingFlag, OnboardingStateCheckmark } from '~/client';

export const userHiringCheckmarks: Record<HiringCheckmark, { label: string }> = {
  application_completed: { label: 'Application completed' },
  good_to_hire: { label: 'Good to hire' },
  do_not_hire: { label: 'Do NOT hire' },
  social_media_checked: { label: 'Social media checked' },
};

export const userOnboardingFlags: Record<OnboardingFlag, { label: string }> = {
  canvasser_info_filled: { label: 'Canvasser info filled' },
  documents_uploaded: { label: 'Documents uploaded' },
  w9_signed: { label: 'W-9 signed' },
  voice_sample_recorded: { label: 'Verification sample provided' },
  branch_configured: { label: 'Branch configured' },
  checkr_checked: { label: 'Checkr checked' },
  profile_filled: { label: 'Profile filled' },
};

// Merged labels keyed by the unified OnboardingStateCheckmark (= HiringCheckmark | OnboardingFlag).
// No cast needed: each source record's keys are members of the union.
export const onboardingStateLabels: Record<OnboardingStateCheckmark, { label: string }> = {
  ...userHiringCheckmarks,
  ...userOnboardingFlags,
};

export function getOnboardingStateLabel(checkmark: OnboardingStateCheckmark): { label: string } {
  return onboardingStateLabels[checkmark] ?? { label: snakeCaseToCapitalizedCase(checkmark) };
}

// Negated labels for contexts that surface a step as a problem (i.e. NOT completed),
// such as the project assignments "Onboarding issues" block. Phrased explicitly rather
// than derived from the positive label so wording stays natural per step.
export const onboardingFlagMissingLabels: Record<OnboardingFlag, string> = {
  canvasser_info_filled: 'Canvasser info NOT filled',
  documents_uploaded: 'Documents NOT uploaded',
  w9_signed: 'W-9 NOT signed',
  voice_sample_recorded: 'Verification sample NOT provided',
  branch_configured: 'Branch NOT configured',
  checkr_checked: 'Checkr NOT checked',
  profile_filled: 'Profile NOT filled',
};

export function getOnboardingFlagMissingLabel(flag: OnboardingFlag): string {
  return onboardingFlagMissingLabels[flag] ?? snakeCaseToCapitalizedCase(flag);
}

// Render/iteration order used by the selector and the URL util: hiring checkmarks first
// (including do_not_hire), then onboarding steps.
export const onboardingStateCheckmarkOrder: OnboardingStateCheckmark[] = [
  'application_completed',
  'social_media_checked',
  'good_to_hire',
  'do_not_hire',
  'canvasser_info_filled',
  'documents_uploaded',
  'w9_signed',
  'voice_sample_recorded',
  'branch_configured',
  'checkr_checked',
  'profile_filled',
];
